import { useState, useEffect } from "react";
import {
  crearEvaluacionPsico,
  actualizarEvaluacionPsico,
} from "../../servicios/evaluacionPsico";
import { listarEvaluacionesIntegrales } from "../../servicios/evaluacionIntegral";
import { crearSubdimensionItem } from "../../servicios/subdimensionItems";

const ITEMS = [
  { id: 1, descripcion: "Se comunica de forma espontánea" },
  { id: 2, descripcion: "Se comunica de forma guiada" },
  { id: 3, descripcion: "Participa en conversaciones espontáneas" },
  { id: 4, descripcion: "Pronunciación clara" },
  { id: 5, descripcion: "Usa oraciones completas" },
];

function EvaluacionPsicoForm({ evaluacion, onSuccess }) {
  const isEdit = !!evaluacion;

  const [evaluacionIntegral, setEvaluacionIntegral] = useState(
    evaluacion?.evaluacion_integral || ""
  );
  const [evaluador, setEvaluador] = useState(evaluacion?.evaluador || "");
  const [fecha, setFecha] = useState(evaluacion?.fecha || "");
  const [observaciones, setObservaciones] = useState(
    evaluacion?.observaciones || ""
  );

  const [integrales, setIntegrales] = useState([]);
  const [valores, setValores] = useState(
    ITEMS.reduce((acc, item) => ({ ...acc, [item.id]: 0 }), {})
  );

  useEffect(() => {
    listarEvaluacionesIntegrales().then(setIntegrales).catch(console.error);
  }, []);

  const cambiarValor = (id, val) => {
    setValores((prev) => ({ ...prev, [id]: val }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const payload = {
      evaluacion_integral: evaluacionIntegral,
      evaluador,
      fecha,
      observaciones,
    };

    try {
      let resp;
      if (isEdit) {
        resp = await actualizarEvaluacionPsico(evaluacion.id, payload);
      } else {
        resp = await crearEvaluacionPsico(payload);
      }

      const evalId = resp.id;

      for (const item of ITEMS) {
        await crearSubdimensionItem({
          evaluacion: evalId,
          area: "Habilidades Comunicativas",
          descripcion: item.descripcion,
          valor: valores[item.id],
        });
      }

      alert("✔ Guardado correctamente");
      onSuccess();

    } catch (error) {
      console.error(error);
      alert("❌ Error al guardar");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="bg-light p-3 border rounded">

      {/* EVALUACION INTEGRAL */}
      <div className="mb-3">
        <label className="form-label">Evaluación integral:</label>
        <select
          className="form-select"
          value={evaluacionIntegral}
          onChange={(e) => setEvaluacionIntegral(e.target.value)}
        >
          <option value="">Seleccione una...</option>
          {integrales.map((ei) => (
            <option key={ei.id} value={ei.id}>
              {ei.id}
            </option>
          ))}
        </select>
      </div>

      {/* EVALUADOR */}
      <div className="mb-3">
        <label className="form-label">Evaluador:</label>
        <input
          className="form-control"
          value={evaluador}
          onChange={(e) => setEvaluador(e.target.value)}
        />
      </div>

      {/* FECHA */}
      <div className="mb-3">
        <label className="form-label">Fecha:</label>
        <input
          type="date"
          className="form-control"
          value={fecha}
          onChange={(e) => setFecha(e.target.value)}
        />
      </div>

      {/* TABLA DE ÍTEMS */}
      <h5 className="mt-4 mb-2">I. Habilidades Comunicativas</h5>
      <table className="table table-bordered">
        <thead>
          <tr className="table-secondary">
            <th>Ítem</th>
            <th>1</th>
            <th>2</th>
            <th>3</th>
            <th>4</th>
            <th>0</th>
          </tr>
        </thead>
        <tbody>
          {ITEMS.map((item) => (
            <tr key={item.id}>
              <td>{item.descripcion}</td>
              {[1, 2, 3, 4, 0].map((val) => (
                <td className="text-center" key={val}>
                  <input
                    type="radio"
                    name={`item-${item.id}`}
                    checked={valores[item.id] === val}
                    onChange={() => cambiarValor(item.id, val)}
                  />
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>

      {/* OBSERVACIONES */}
      <div className="mb-3">
        <label className="form-label">Observaciones:</label>
        <textarea
          className="form-control"
          rows={3}
          value={observaciones}
          onChange={(e) => setObservaciones(e.target.value)}
        />
      </div>

      {/* BOTÓN */}
      <button className="btn btn-success w-100">
        {isEdit ? "Actualizar evaluación" : "Crear evaluación"}
      </button>
    </form>
  );
}

export default EvaluacionPsicoForm;
